import re

action_items = {
    "Alice": 1,
    "Bob": 1,
    "Carol": 1,
    "Everyone": 1
}

# Update action item counts for each person
for key, value in action_items.items():
    if key != "Everyone":
        print(f"Updating profile.txt for {key} with Action Items: {value}")

# Start updating the profile.txt files
import os
root_dir = "/workspace/users"
for dir_name in os.listdir(root_dir):
    dir_path = os.path.join(root_dir, dir_name)
    if os.path.isdir(dir_path):
        file_path = os.path.join(dir_path, "profile.txt")
        if os.path.exists(file_path):
            with open(file_path, "r") as file:
                lines = file.readlines()
            with open(file_path, "w") as file:
                for line in lines:
                    if line.startswith("Action Items:"):
                        file.write(f"Action Items: {action_items.get(dir_name, 0)}\n")
                    else:
                        file.write(line)
